        {
            "name": "Derivative weight",
            "type": "line",
            "showSymbol": False,
            "yAxisIndex": 1,
            "data": [[row[0], row[2]] for row in data],
            "lineStyle": {"width": 1.5, "color": "#d62728"}
        }
    ]
}

print(json.dumps({
    "figures": [{
        "name": "raw_reversed_temperature",
